(6808313, 1024242, 65319, '<td valign="top">My favorite in this challenge...10.  Good Luck!</td>', 'My favorite in this challenge...10.  Good Luck!', '2012-07-04 02:21:57.000000', NULL, 1),
(6808314, 1023490, 65319, '<td valign="top">I''d like this one for my wall...10</td>', 'I''d like this one for my wall...10', '2012-07-04 02:22:50.000000', NULL, 1),
(6808493, 1024129, 149484, '<td valign="top">Such a beautiful picture but abstract?</td>', 'Such a beautiful picture but abstract?', '2012-07-04 07:10:52.000000', NULL, 1),
(6808519, 1024283, 23394, '<td valign="top">one of my top picks.  that being said, i would have cropped out the damsel altogether.  the image is perfectly lovely without its distraction.  given the nature of this challenge, i scored based on what i would enjoy seeing on my wall, and this is beautiful.</td>', 'one of my top picks.  that being said, i would have cropped out the damsel altogether.  the image is perfectly lovely without its distraction.  given the nature of this challenge, i scored based on what i would enjoy seeing on my wall, and this is beautiful.', '2012-07-04 08:17:54.000000', NULL, 1),
(6808527, 1024159, 23394, '<td valign="top">one of my top picks.  given the nature of this challenge, i scored based on what i would enjoy seeing on my wall, and this is beautiful.  if i were to change anything, it would be to give it a more uniform crop.  if i were to print it (that is, do something other than enter it in a challenge), i would extend the left side a bit.  nicely done!<br/> <br/>btw, i hope it does better than mine did (nearly 7 years ago...)<br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=141564" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_challenge/0-999/303/120/Copyrighted_Image_Reuse_Prohibited_141564.jpg'', strrpos(''//images.dpchallenge.com/images_challenge/0-999/303/120/Copyrighted_Image_Reuse_Prohibited_141564.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_challenge/0-999/303/120/Copyrighted_Image_Reuse_Prohibited_141564.jpg"/></a></td>', 'one of my top picks.  given the nature of this challenge, i scored based on what i would enjoy seeing on my wall, and this is beautiful.  if i were to change anything, it would be to give it a more uniform crop.  if i were to print it (that is, do something other than enter it in a challenge), i would extend the left side a bit.  nicely done! btw, i hope it does better than mine did (nearly 7 years ago...)', '2012-07-04 08:24:24.000000', NULL, 1),
(6808528, 1023839, 23394, '<td valign="top">i really like this.  a little on the dark side, but not enough for me to mark it down.  must have been fun, trying to pull this off.  must have been even more fun, trying to decide which one to enter.</td>', 'i really like this.  a little on the dark side, but not enough for me to mark it down.  must have been fun, trying to pull this off.  must have been even more fun, trying to decide which one to enter.', '2012-07-04 08:29:04.000000', NULL, 1),
(6808530, 1024172, 23394, '<td valign="top">awesome.  so clean.  i''m scoring it high, but will be wishing i could take my vote back if you don''t provide any notes about how you did this.</td>', 'awesome.  so clean.  i''m scoring it high, but will be wishing i could take my vote back if you don''t provide any notes about how you did this.', '2012-07-04 08:30:52.000000', NULL, 1),
(6808531, 1023550, 23394, '<td valign="top">hope you don''t get robbed by thumb-voters.  this is one of my top picks.  given the nature of this challenge, i scored based on what i would enjoy seeing on my wall, and this is beautiful.</td>', 'hope you don''t get robbed by thumb-voters.  this is one of my top picks.  given the nature of this challenge, i scored based on what i would enjoy seeing on my wall, and this is beautiful.', '2012-07-04 08:32:29.000000', NULL, 1),
(6808532, 1024194, 23394, '<td valign="top">beautiful!  one of my top pics.  if i were to change anything, it would be to crop 5-7% off the right; that red is a distraction that unbalances the image as a whole.  given the nature of this challenge, i scored based on what i would enjoy seeing on my wall, and this would fit my vision of a perfect wall.</td>', 'beautiful!  one of my top pics.  if i were to change anything, it would be to crop 5-7% off the right; that red is a distraction that unbalances the image as a whole.  given the nature of this challenge, i scored based on what i would enjoy seeing on my wall, and this would fit my vision of a perfect wall.', '2012-07-04 08:35:15.000000', NULL, 1),
(6808534, 1024222, 23394, '<td valign="top">the essence of an abstract!  one of my top pics for the challenge!  i can offer nothing more than to say i hope others can find the time to just sit back and take this in before rushing off to whatever''s next.  given the nature of this challenge, i scored based on what i would enjoy seeing on my wall, and this would fit my vision of a perfect wall.</td>', 'the essence of an abstract!  one of my top pics for the challenge!  i can offer nothing more than to say i hope others can find the time to just sit back and take this in before rushing off to whatever''s next.  given the nature of this challenge, i scored based on what i would enjoy seeing on my wall, and this would fit my vision of a perfect wall.', '2012-07-04 08:37:18.000000', NULL, 1),
(6808535, 1024010, 23394, '<td valign="top">quite lovely, most definitely capturing the essence of abstraction.  perhaps a little dark and imbalanced, but not enough for me to mark it down.</td>', 'quite lovely, most definitely capturing the essence of abstraction.  perhaps a little dark and imbalanced, but not enough for me to mark it down.', '2012-07-04 08:38:17.000000', NULL, 1),
(6808538, 1024228, 23394, '<td valign="top">nice!  bet you had a tough time with the selection.  it''s easy to throw out the misses, but to pick between the handful of killer shots - that''s tough!  hope to see your outtakes after the challenge!</td>', 'nice!  bet you had a tough time with the selection.  it''s easy to throw out the misses, but to pick between the handful of killer shots - that''s tough!  hope to see your outtakes after the challenge!', '2012-07-04 08:39:33.000000', NULL, 1),
(6808539, 1024285, 23394, '<td valign="top">hope you don''t get robbed by the thumb-voters.  this is just exquisite!</td>', 'hope you don''t get robbed by the thumb-voters.  this is just exquisite!', '2012-07-04 08:40:44.000000', NULL, 1),
(6808540, 1024141, 23394, '<td valign="top">i love everything but the colors, and that''s probably just my personal taste.</td>', 'i love everything but the colors, and that''s probably just my personal taste.', '2012-07-04 08:42:29.000000', NULL, 1),
(6808541, 1023490, 23394, '<td valign="top">wow!  i''m going to be pretty disappointed if you don''t provide some notes on this shot.</td>', 'wow!  i''m going to be pretty disappointed if you don''t provide some notes on this shot.', '2012-07-04 08:43:43.000000', NULL, 1),
(6808544, 1024005, 23394, '<td valign="top">nicely done!  i like it as is, but can''t but think i''d like it more if it was a little lighter (but that''s just a matter of personal taste, not necessarily something to be imposed on you and your vision).</td>', 'nicely done!  i like it as is, but can''t but think i''d like it more if it was a little lighter (but that''s just a matter of personal taste, not necessarily something to be imposed on you and your vision).', '2012-07-04 08:45:41.000000', NULL, 1),
(6808547, 1023815, 23394, '<td valign="top">meets the challenge, but doesn''t really grab me.  maybe if you''d cropped in to exclude the outer ring it would look more like a piece of abstract art than a documentary shot.</td>', 'meets the challenge, but doesn''t really grab me.  maybe if you''d cropped in to exclude the outer ring it would look more like a piece of abstract art than a documentary shot.', '2012-07-04 08:47:54.000000', NULL, 1),
(6808552, 1024287, 107708, '<td valign="top">Perfect</td>', 'Perfect', '2012-07-04 08:49:34.000000', NULL, 1),
(6808554, 1024222, 107708, '<td valign="top">Lovely soft abstract</td>', 'Lovely soft abstract', '2012-07-04 08:49:47.000000', NULL, 1),
(6808555, 1024242, 107708, '<td valign="top">Dramatic</td>', 'Dramatic', '2012-07-04 08:49:57.000000', NULL, 1),
(6808562, 1024249, 23394, '<td valign="top">love the idea.  <b>really </b>love the idea.  but the execution falls a little short for me.  the more i look at it (and i''ve been looking at it over a minute, now), the more i''m taken in by it, but i feel like i''m doing more work wondering what could have been, rather than appreciating what was.</td>', 'love the idea.  really love the idea.  but the execution falls a little short for me.  the more i look at it (and i''ve been looking at it over a minute, now), the more i''m taken in by it, but i feel like i''m doing more work wondering what could have been, rather than appreciating what was.', '2012-07-04 08:53:09.000000', NULL, 1),
(6808566, 1023116, 23394, '<td valign="top">not really an abstract (for me), but all the same, a lovely image.</td>', 'not really an abstract (for me), but all the same, a lovely image.', '2012-07-04 08:53:42.000000', NULL, 1),
(6808573, 1023440, 23394, '<td valign="top">you must have had a blast, shooting this.  i know full well what it''s like, having other adults thinking, "what the h377 are they doing, chasing that kid with a camera?!?"  good times, good times!  and nicely done!</td>', 'you must have had a blast, shooting this.  i know full well what it''s like, having other adults thinking, "what the h377 are they doing, chasing that kid with a camera?!?"  good times, good times!  and nicely done!', '2012-07-04 08:55:49.000000', NULL, 1),
(6808583, 1024005, 96721, '<td valign="top">This would be SOOO good had the background just been plain black IMHO as it stands a 6 for your lovely moving poppies.</td>', 'This would be SOOO good had the background just been plain black IMHO as it stands a 6 for your lovely moving poppies.', '2012-07-04 08:59:51.000000', NULL, 1),
(6808586, 1023118, 23394, '<td valign="top">beautiful abstract.  you can take the following with a grain of salt, because it''s my personal take, in no way meant to take away from your personal vision.  if this were mine, i''d have cropped off 35% off the left, 25% off the right, then rotated it 90ccw, giving it a more balanced left vs right with a fluid compromise in the middle.  as is, there are too many competing elements.</td>', 'beautiful abstract.  you can take the following with a grain of salt, because it''s my personal take, in no way meant to take away from your personal vision.  if this were mine, i''d have cropped off 35% off the left, 25% off the right, then rotated it 90ccw, giving it a more balanced left vs right with a fluid compromise in the middle.  as is, there are too many competing elements.', '2012-07-04 09:01:47.000000', NULL, 1),
(6808588, 1023349, 23394, '<td valign="top">nice, and soothing, but not keeping my attention.</td>', 'nice, and soothing, but not keeping my attention.', '2012-07-04 09:04:31.000000', NULL, 1),
(6808591, 1024078, 23394, '<td valign="top">i think i see <a href="//en.wikipedia.org/wiki/File:Phyllis_Diller_Allan_Warren.jpg" rel="nofollow" target="_blank">phyliss diller</a>!</td>', 'i think i see phyliss diller!', '2012-07-04 09:06:07.000000', NULL, 1),
(6808598, 1024233, 23394, '<td valign="top">sweet!  personally, i''d have cropped off the bottom 30% (the empty area at the bottom left is wasted), and maybe have played with a temperature shift (the browns don''t really compliment the greens).  just my personal taste, no reflection on your vision.</td>', 'sweet!  personally, i''d have cropped off the bottom 30% (the empty area at the bottom left is wasted), and maybe have played with a temperature shift (the browns don''t really compliment the greens).  just my personal taste, no reflection on your vision.', '2012-07-04 09:10:46.000000', NULL, 1),
(6808604, 1024260, 23394, '<td valign="top">nice idea, but the execution isn''t really working for me.  i really don''t enjoy the yellowish tint.  too much rock - it grossly outweighs the spray.  this could be an interesting study between fixed and fluid, and could be possible with a much tighter crop.</td>', 'nice idea, but the execution isn''t really working for me.  i really don''t enjoy the yellowish tint.  too much rock - it grossly outweighs the spray.  this could be an interesting study between fixed and fluid, and could be possible with a much tighter crop.', '2012-07-04 09:15:18.000000', NULL, 1),
(6808608, 1024055, 23394, '<td valign="top">nice idea, but i personally don''t like the outer corners and would have cropped in to lose them.</td>', 'nice idea, but i personally don''t like the outer corners and would have cropped in to lose them.', '2012-07-04 09:16:15.000000', NULL, 1),
(6808613, 1023808, 23394, '<td valign="top">great idea!  love the colors.  personally, i would have cropped off the top 40%.  as is, to me, the top is wasted and unbalances an otherwise superbly dynamic image.</td>', 'great idea!  love the colors.  personally, i would have cropped off the top 40%.  as is, to me, the top is wasted and unbalances an otherwise superbly dynamic image.', '2012-07-04 09:18:43.000000', NULL, 1),
(6808614, 1024297, 23394, '<td valign="top">nice!</td>', 'nice!', '2012-07-04 09:19:07.000000', NULL, 1),
(6808626, 1023454, 23394, '<td valign="top">take this with a grain of salt, it''s my personal reaction, nothing to do with your personal vision.  this just doesn''t do anything for me.  i don''t like the processing.  i don''t find the basic color temperature appealing.  i like the bird, but find the feeders extremely distracting.  i LOVE the bird.  in fact, i would have cropped this vertical, enough to have been able to clone out the edge of the feeder.  and then maybe toned it bw.  then i would feel like i had a nice piece of abstract art.  again, just my personal take on it.</td>', 'take this with a grain of salt, it''s my personal reaction, nothing to do with your personal vision.  this just doesn''t do anything for me.  i don''t like the processing.  i don''t find the basic color temperature appealing.  i like the bird, but find the feeders extremely distracting.  i LOVE the bird.  in fact, i would have cropped this vertical, enough to have been able to clone out the edge of the feeder.  and then maybe toned it bw.  then i would feel like i had a nice piece of abstract art.  again, just my personal take on it.', '2012-07-04 09:24:46.000000', NULL, 1),
(6808637, 1024129, 23394, '<td valign="top">nice idea, but way too dark.  also, as far as the challenge goes, this is more of a traditional landscape than an abstract of something in motion.  just for yourself, try this: go back, put your camera in tv mode and set the shutter speed to about 1/15 to start, put your camera on a tripod, and put your camera down as close to the water as you feel comfortable, and start shooting.  try different shutter speeds and try different exposures.  try capturing the feel of the water moving through the rocks.  there is an opportunity here to capture a nice piece of wall art, but you have to work at it.</td>', 'nice idea, but way too dark.  also, as far as the challenge goes, this is more of a traditional landscape than an abstract of something in motion.  just for yourself, try this: go back, put your camera in tv mode and set the shutter speed to about 1/15 to start, put your camera on a tripod, and put your camera down as close to the water as you feel comfortable, and start shooting.  try different shutter speeds and try different exposures.  try capturing the feel of the water moving through the rocks.  there is an opportunity here to capture a nice piece of wall art, but you have to work at it.', '2012-07-04 09:31:41.000000', NULL, 1),
(6808639, 1023755, 23394, '<td valign="top">nice idea, nice opportunity, but doesn''t really work for me as far as this challenge goes (that is, i don''t really see this as an abstract).  also not a fan of all that empty space.</td>', 'nice idea, nice opportunity, but doesn''t really work for me as far as this challenge goes (that is, i don''t really see this as an abstract).  also not a fan of all that empty space.', '2012-07-04 09:33:30.000000', NULL, 1),
(6808641, 1024065, 23394, '<td valign="top">just doesn''t do anything for me.  maybe if there was less tree in the top.</td>', 'just doesn''t do anything for me.  maybe if there was less tree in the top.', '2012-07-04 09:34:25.000000', NULL, 1),
(6808647, 1024142, 23394, '<td valign="top">very abstract, i will give it that, but not really capturing me.  the negative space is not contributing to the image.  the dark parts of the subject seem to meld into the dark areas of the background, producing an unbalanced image.</td>', 'very abstract, i will give it that, but not really capturing me.  the negative space is not contributing to the image.  the dark parts of the subject seem to meld into the dark areas of the background, producing an unbalanced image.', '2012-07-04 09:37:50.000000', NULL, 1),
(6808648, 1024210, 23394, '<td valign="top">not enough motion to create any interest.</td>', 'not enough motion to create any interest.', '2012-07-04 09:38:24.000000', NULL, 1),
(6808650, 1024211, 23394, '<td valign="top">i see what you''re after, but am not taken away by the results.  not enjoying the colors and the contrast.  as is, it''s more a picture of rocks and leaves (something concrete, tangible), rather than a moving stream (which could be fluid and abstract).</td>', 'i see what you''re after, but am not taken away by the results.  not enjoying the colors and the contrast.  as is, it''s more a picture of rocks and leaves (something concrete, tangible), rather than a moving stream (which could be fluid and abstract).', '2012-07-04 09:40:25.000000', NULL, 1),
(6808651, 1024158, 23394, '<td valign="top">nice idea, but comes across to me a little over-cooked.</td>', 'nice idea, but comes across to me a little over-cooked.', '2012-07-04 09:41:15.000000', NULL, 1),
(6808653, 1024299, 23394, '<td valign="top">i like the idea, but feel the negative space on the right doesn''t really contribute.  feel the same way about the blown highlights.  just my personal taste, though.</td>', 'i like the idea, but feel the negative space on the right doesn''t really contribute.  feel the same way about the blown highlights.  just my personal taste, though.', '2012-07-04 09:42:44.000000', NULL, 1),
(6808654, 1023059, 23394, '<td valign="top">not really getting a sense of motion here.  the high contrast also makes it hard to look at for long.</td>', 'not really getting a sense of motion here.  the high contrast also makes it hard to look at for long.', '2012-07-04 09:43:31.000000', NULL, 1),
(6808656, 1024023, 23394, '<td valign="top">lotta color there...be careful what you spill that on!</td>', 'lotta color there...be careful what you spill that on!', '2012-07-04 09:44:41.000000', NULL, 1),
